B.aRc=new A.bI("major_00","\u0428\u0443\u0442","0","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0412\u043e\u0437\u0434\u0443\u0445","\u0423\u0440\u0430\u043d",B.avH,"\u0428\u0443\u0442 \u043f\u0440\u0435\u0434\u0432\u0435\u0449\u0430\u0435\u0442 \u043d\u043e\u0432\u044b\u0435 \u043d\u0430\u0447\u0438\u043d\u0430\u043d\u0438\u044f \u0438 \u043f\u0440\u043e\u0434\u0443\u043c\u0430\u043d\u043d\u044b\u0439 \u0440\u0438\u0441\u043a. \u041d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u043e\u0437\u0434\u043d\u043e \u043d\u0430\u0447\u0430\u0442\u044c \u0437\u0430\u043d\u043e\u0432\u043e \u0438 \u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c \u0436\u0435\u043b\u0430\u043d\u0438\u044e \u0441\u0432\u043e\u0435\u0433\u043e \u0441\u0435\u0440\u0434\u0446\u0430. \u041f\u0440\u0435\u0434\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u043f\u0443\u0442\u0435\u0448\u0435\u0441\u0442\u0432\u0438\u0435 \u043d\u0435 \u043b\u0438\u0448\u0435\u043d\u043e \u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0435\u0439, \u043d\u043e \u043f\u0440\u0438\u0448\u043b\u043e \u0432\u0440\u0435\u043c\u044f \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0448\u0430\u0433 \u0432\u0435\u0440\u044b. \u042d\u0442\u0430 \u043a\u0430\u0440\u0442\u0430 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0445\u043e\u0440\u043e\u0448\u0438\u043c \u043f\u0440\u0435\u0434\u0437\u043d\u0430\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u0434\u043b\u044f \u0442\u0435\u0445, \u043a\u0442\u043e \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442 \u043d\u043e\u0432\u044b\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0438 \u043e\u0431\u0443\u0447\u0430\u0435\u0442\u0441\u044f, \u043f\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0438 \u0440\u0430\u0437\u0443\u043c\u043d\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f; \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0434\u043b\u044f \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u043c\u0430 \u0438 \u0441\u0432\u0435\u0436\u0435\u0433\u043e \u0432\u0437\u0433\u043b\u044f\u0434\u0430. \u0427\u0442\u043e \u0431\u044b \u0432\u044b \u043d\u0438 \u043d\u0430\u0447\u0430\u043b\u0438 \u0441\u0435\u0439\u0447\u0430\u0441, \u0432\u0441\u0435 \u043f\u043e\u0439\u0434\u0435\u0442 \u0445\u043e\u0440\u043e\u0448\u043e, \u0435\u0441\u043b\u0438 \u0432\u044b \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \xab\u0428\u0443\u0442\xbb \u043f\u0440\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0431\u0435\u0437\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430: \u0440\u043e\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0432\u043f\u0435\u0440\u0435\u0434\u0438 \u043c\u043e\u0437\u0433\u0430. \u041d\u0435 \u043e\u0431\u0434\u0443\u043c\u044b\u0432\u0430\u044f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043a\u0438, \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442\u0441\u044f \u043d\u0435\u0440\u0430\u0437\u0443\u043c\u043d\u044b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f. \u0422\u0449\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u043e\u0434\u0443\u043c\u0430\u0439\u0442\u0435, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u043d\u043e\u0432\u044b\u0439 \u043f\u043e\u0434\u0445\u043e\u0434 \u043a \u0440\u0430\u0431\u043e\u0442\u0435, \u0438 \u0432\u043e\u0437\u0434\u0435\u0440\u0436\u0438\u0442\u0435\u0441\u044c \u043e\u0442 \u044d\u043c\u043e\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432, \u043f\u043e\u043a\u0430 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442\u0435 \u0443\u0432\u0435\u0440\u0435\u043d\u044b \u0432 \u0441\u0432\u043e\u0435\u0439 \u043f\u0440\u0430\u0432\u043e\u0442\u0435.","\u0428\u0443\u0442 \u2014 \u043d\u0435\u0432\u0438\u043d\u043d\u044b\u0439 \u0438\u0441\u043a\u0430\u0442\u0435\u043b\u044c \u043f\u0440\u0438\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c\u0441\u044f \u0432 \u0432\u0430\u0436\u043d\u043e\u0435 \u043f\u0443\u0442\u0435\u0448\u0435\u0441\u0442\u0432\u0438\u0435. \u0421 \u0433\u043e\u043b\u043e\u0432\u043e\u0439, \u043f\u043e\u043b\u043d\u043e\u0439 \u043d\u0430\u0434\u0435\u0436\u0434, \u043e\u043d \u0441\u043a\u043e\u0440\u0435\u0435 \u0438\u0434\u0435\u0430\u043b\u0438\u0441\u0442\u0438\u0447\u0435\u043d, \u0447\u0435\u043c \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u043d. \u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0430\u044f \u0441\u043e\u0431\u0430\u0447\u043a\u0430, \u0438\u0434\u0443\u0449\u0430\u044f \u0437\u0430 \u043d\u0438\u043c \u043f\u043e \u043f\u044f\u0442\u0430\u043c, \u043f\u044b\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0434\u0438\u0442\u044c \u0435\u0433\u043e \u043e \u043d\u0430\u0434\u0432\u0438\u0433\u0430\u044e\u0449\u0435\u0439\u0441\u044f \u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438, \u043d\u043e \u0428\u0443\u0442 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432 \u0431\u043b\u0430\u0436\u0435\u043d\u043d\u043e\u043c \u043d\u0435\u0432\u0435\u0434\u0435\u043d\u0438\u0438 \u043e \u0440\u0438\u0441\u043a\u0435, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u043e\u043d \u043f\u043e\u0434\u0432\u0435\u0440\u0433\u0430\u0435\u0442\u0441\u044f, \u0441\u043f\u0443\u0441\u0442\u0438\u0432\u0448\u0438\u0441\u044c \u0441\u043e \u0441\u043a\u0430\u043b\u044b.","\u041f\u0440\u044b\u0433\u0430\u0439, \u043d\u043e \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438.","assets/tarot/m00.jpg")
B.aoy=s(["\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435","\u041a\u0440\u0435\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c","\u0421\u0438\u043b\u0430 \u0432\u043e\u043b\u0438","\u041f\u0440\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u0435","\u041d\u0430\u0432\u044b\u043a"],t.s)
B.aRu=new A.bI("major_01","\u041c\u0430\u0433","I","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0412\u043e\u0437\u0434\u0443\u0445","\u041c\u0435\u0440\u043a\u0443\u0440\u0438\u0439",B.aoy,"\u041f\u0440\u0438\u0448\u043b\u043e \u0432\u0440\u0435\u043c\u044f \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u2014 \u043e\u0431\u0449\u0430\u0442\u044c\u0441\u044f \u0438 \u0432\u044b\u0440\u0430\u0436\u0430\u0442\u044c \u0441\u0432\u043e\u0438 \u0438\u0434\u0435\u0438 \u0438 \u0436\u0435\u043b\u0430\u043d\u0438\u044f. \u042d\u0442\u043e \u043a\u0430\u0440\u0442\u0430 \u0438\u0437\u043e\u0431\u0440\u0435\u0442\u0430\u0442\u0435\u043b\u044f, \u043f\u0443\u0442\u0435\u0448\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0430, \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u044f \u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u044f, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043e\u043d\u0430 \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u0435\u0442 \u0432\u0430\u0441 \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0441\u0432\u043e\u0439 \u043a\u0440\u0443\u0433\u043e\u0437\u043e\u0440. \u0423 \u0432\u0430\u0441 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0441\u0442\u0440\u0435\u043c\u043b\u0435\u043d\u0438\u0435 \u0443\u0441\u043a\u043e\u0440\u0438\u0442\u044c \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0441\u0432\u043e\u0438\u0445 \u043f\u043b\u0430\u043d\u043e\u0432. \u0411\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0432\u043e\u043b\u0448\u0435\u0431\u043d\u043e\u0439 \u043f\u0430\u043b\u043e\u0447\u043a\u0435 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044c \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u0435, \u0447\u0442\u043e \u0432\u044b \u043f\u043e\u0436\u0435\u043b\u0430\u0435\u0442\u0435. \u041e\u043d \u0441\u043e\u0432\u0435\u0442\u0443\u0435\u0442 \u0432\u0430\u043c \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0441\u0432\u043e\u0438 \u043d\u0430\u0432\u044b\u043a\u0438 \u0438 \u0442\u0430\u043b\u0430\u043d\u0442\u044b \u0438 \u043e\u0431\u0440\u0435\u0441\u0442\u0438 \u0441\u0432\u043e\u044e \u0441\u0438\u043b\u0443.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0412\u043e\u043b\u0448\u0435\u0431\u043d\u0438\u043a \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043e\u0431\u043c\u0430\u043d\u0449\u0438\u043a\u043e\u043c \u2014 \u044d\u0442\u0430 \u043a\u0430\u0440\u0442\u0430 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c, \u0447\u0442\u043e \u0432\u0430\u0441 \u0432\u0432\u0435\u043b \u0432 \u0437\u0430\u0431\u043b\u0443\u0436\u0434\u0435\u043d\u0438\u0435 \u043e\u0447\u0430\u0440\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043c\u0430\u043d\u0438\u043f\u0443\u043b\u044f\u0442\u043e\u0440. \u0422\u043e, \u0447\u0442\u043e \u0432\u044b \u0432\u0438\u0434\u0438\u0442\u0435, \u2014 \u044d\u0442\u043e \u043d\u0435 \u0442\u043e, \u0447\u0442\u043e \u0432\u044b \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0435, \u0438 \u0432\u0441\u0435 \u044d\u0442\u043e \u043f\u043e\u043a\u0430\u0437\u0443\u0445\u0430, \u0430 \u043d\u0435 \u043f\u0440\u0430\u0432\u0434\u0430. \u0412 \u0432\u0430\u0448\u0438\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u0430\u0445 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u044b\u0439 \u041c\u0430\u0433 \u043c\u043e\u0436\u0435\u0442 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u043d\u0430 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u043a\u0438\u0439 \u0431\u043b\u043e\u043a, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0432\u044b \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u0435\u0442\u0435, \u0447\u0442\u043e \u0440\u0430\u0437\u0440\u044b\u0432\u0430\u0435\u0442\u0435\u0441\u044c \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u043f\u0443\u0442\u044f\u043c\u0438. \u041f\u0440\u0438\u0448\u043b\u043e \u0432\u0440\u0435\u043c\u044f \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0435\u043c\u0443 \u043f\u043e\u0441\u0432\u044f\u0442\u0438\u0442\u044c \u0441\u0435\u0431\u044f.","\u0412\u043e\u043b\u0448\u0435\u0431\u043d\u0438\u043a \u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438, \u0432 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0442\u0435 \u0441 \u0432\u043e\u043b\u0448\u0435\u0431\u043d\u043e\u0439 \u043f\u0430\u043b\u043e\u0447\u043a\u043e\u0439 \u0438 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u043d\u043e\u0441\u0442\u044f\u043c\u0438 \u0441\u0432\u043e\u0435\u0433\u043e \u0440\u0435\u043c\u0435\u0441\u043b\u0430: \u0441\u0438\u043c\u0432\u043e\u043b\u0430\u043c\u0438 \u043c\u0430\u0441\u0442\u0438 \u041f\u0435\u043d\u0442\u0430\u043a\u043b\u044f, \u0427\u0430\u0448\u0438, \u041c\u0435\u0447\u0430 \u0438 \u0416\u0435\u0437\u043b\u0430, \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u043c\u0438 \u0447\u0435\u0442\u044b\u0440\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430. \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044f \u044d\u0442\u0438 \u0431\u0430\u0437\u043e\u0432\u044b\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b, \u043e\u043d \u043d\u0430\u043c\u0435\u0440\u0435\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u0440\u0430\u043d\u0441\u043c\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0438\u0445. \u0411\u0443\u0434\u0443\u0447\u0438 \u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u043e\u043c \u043c\u0435\u0436\u0434\u0443 \u0437\u0435\u043c\u043b\u0435\u0439 \u0438 \u043d\u0435\u0431\u043e\u043c, \u041c\u0430\u0433 \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u0437\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u0442\u0432\u043e.","\u041f\u0440\u043e\u044f\u0432\u043b\u044f\u0439\u0442\u0435 \u0441\u0432\u043e\u0438 \u0436\u0435\u043b\u0430\u043d\u0438\u044f.","assets/tarot/m01.jpg")
B.avf=s(["\u0421\u0435\u043a\u0440\u0435\u0442\u044b","\u0418\u043d\u0442\u0443\u0438\u0446\u0438\u044f","\u041c\u0443\u0434\u0440\u043e\u0441\u0442\u044c","\u0422\u0430\u0439\u043d\u0430","\u0414\u0443\u0445\u043e\u0432\u043d\u043e\u0441\u0442\u044c"],t.s)
B.aRZ=new A.bI("major_02","\u0412\u0435\u0440\u0445\u043e\u0432\u043d\u0430\u044f \u0416\u0440\u0438\u0446\u0430","II","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0412\u043e\u0434\u0430","\u041b\u0443\u043d\u0430",B.avf,"\u0421\u043a\u0440\u044b\u0442\u044b\u0435 \u0437\u043d\u0430\u043d\u0438\u044f, \u0438\u043d\u0442\u0443\u0438\u0446\u0438\u044f, \u043f\u0441\u0438\u0445\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u044b\u0442 \u0438 \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0447\u0442\u044b \u2014 \u0434\u0430\u0440\u044b \u0412\u0435\u0440\u0445\u043e\u0432\u043d\u043e\u0439 \u0416\u0440\u0438\u0446\u044b. \u042d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0434\u043b\u044f \u0438\u043d\u043a\u0443\u0431\u0430\u0446\u0438\u0438 \u0438 \u0443\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u044f, \u0434\u043b\u044f \u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0432 \u0441\u0435\u0431\u044f, \u0443\u0433\u043b\u0443\u0431\u043b\u0435\u043d\u0438\u044f \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u0441\u043e \u0441\u0432\u043e\u0438\u043c \u0432\u044b\u0441\u0448\u0438\u043c \xab\u042f\xbb \u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u044f \u0441\u0432\u043e\u0435\u043c\u0443 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u043c\u0443 \u0437\u043d\u0430\u043d\u0438\u044e. \u0412 \u043f\u043e\u0432\u0441\u0435\u0434\u043d\u0435\u0432\u043d\u043e\u0439 \u0436\u0438\u0437\u043d\u0438 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0438\u043c\u0435\u0435\u0442 \u0440\u0435\u0448\u0430\u044e\u0449\u0435\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435. \u041d\u0430 \u0432\u0430\u0448\u0435\u043c \u0434\u0443\u0445\u043e\u0432\u043d\u043e\u043c \u043f\u0443\u0442\u0438 \u0412\u0435\u0440\u0445\u043e\u0432\u043d\u0430\u044f \u0416\u0440\u0438\u0446\u0430 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 \u0438 \u043d\u0430\u0441\u0442\u0430\u0432\u043d\u0438\u043a\u0430.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0412\u0435\u0440\u0445\u043e\u0432\u043d\u0430\u044f \u0416\u0440\u0438\u0446\u0430 \u043c\u043e\u0436\u0435\u0442 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u043d\u0430 \u043d\u0435\u043f\u043e\u0434\u0445\u043e\u0434\u044f\u0449\u0435\u0433\u043e \u043d\u0430\u0441\u0442\u0430\u0432\u043d\u0438\u043a\u0430 \u0438\u043b\u0438 \u0432\u044b\u0431\u043e\u0440 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043d\u0435\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u0443\u0442\u0438. \u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0432\u044b \u0441\u043b\u0443\u0448\u0430\u0435\u0442\u0435 \u043f\u043b\u043e\u0445\u043e\u0439 \u0441\u043e\u0432\u0435\u0442, \u0438\u043b\u0438 \u043a\u0442\u043e-\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043f\u044b\u0442\u0430\u0442\u044c\u0441\u044f \u0443\u0431\u0435\u0434\u0438\u0442\u044c \u0432\u0430\u0441 \u043f\u043e\u0439\u0442\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u0441\u0432\u043e\u0435\u0439 \u0438\u043d\u0442\u0443\u0438\u0446\u0438\u0438. \u042d\u0442\u043e \u0442\u0430\u043a\u0436\u0435 \u043c\u043e\u0436\u0435\u0442 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u043d\u0430 \u0441\u0435\u043a\u0440\u0435\u0442\u044b, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0434\u043e\u043b\u0436\u043d\u044b \u0431\u044b\u0442\u044c \u0440\u0430\u0441\u043a\u0440\u044b\u0442\u044b.","\u0412\u0435\u0440\u0445\u043e\u0432\u043d\u0430\u044f \u0416\u0440\u0438\u0446\u0430 \u0441\u0442\u043e\u0438\u0442 \u043c\u0435\u0436\u0434\u0443 \u0434\u0432\u0443\u043c\u044f \u043e\u0433\u0440\u043e\u043c\u043d\u044b\u043c\u0438 \u043a\u043e\u043b\u043e\u043d\u043d\u0430\u043c\u0438, \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u043c\u0438 \u0431\u0443\u043a\u0432\u0430\u043c\u0438 B \u0438 J. \u041f\u043e\u0437\u0430\u0434\u0438 \u043d\u0435\u0435 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432\u0443\u0430\u043b\u044c, \u0443\u043a\u0440\u0430\u0448\u0435\u043d\u043d\u0430\u044f \u0433\u0440\u0430\u043d\u0430\u0442\u0430\u043c\u0438; \u043e\u043d\u0430 \u043d\u043e\u0441\u0438\u0442 \u0433\u043e\u043b\u043e\u0432\u043d\u043e\u0439 \u0443\u0431\u043e\u0440 \u0441 \u0440\u043e\u0433\u0430\u043c\u0438 \u0438 \u043b\u0443\u043d\u043e\u0439 \u0438 \u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u0432\u0438\u0442\u043e\u043a \u0441 \u0431\u0443\u043a\u0432\u0430\u043c\u0438 \u0422\u043e\u0440\u044b. \u041e\u043d\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043f\u0440\u0438\u043d\u0446\u0438\u043f \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u0436\u0435\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u2014 \u044d\u043a\u0441\u0442\u0440\u0430\u0441\u0435\u043d\u0441\u0430, \u0430\u0441\u0442\u0440\u043e\u043b\u043e\u0433\u0430 \u0438\u043b\u0438 \u0434\u0443\u0445\u043e\u0432\u043d\u043e\u0433\u043e \u0443\u0447\u0438\u0442\u0435\u043b\u044f.","\u0418\u0441\u0441\u043b\u0435\u0434\u0443\u0439\u0442\u0435 \u0441\u0432\u043e\u044e \u0434\u0443\u0445\u043e\u0432\u043d\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443.","assets/tarot/m02.jpg")
